package com.gazette.pipeline

import org.json.JSONArray
import org.junit.Assert.assertEquals
import org.junit.Test

// The fixture was generated by evaluating the real prompt builders inside
// scripts/extract_test_v3.js, so byte equality here proves the Kotlin prompts
// are the same strings the desktop spike validated.
class PromptsParityTest {

    @Test
    fun prompts_matchJsBuildersByteForByte() {
        val stream = javaClass.getResourceAsStream("/prompts_fixture.json")
            ?: error("prompts_fixture.json missing from test resources")
        val fixture = JSONArray(stream.readBytes().toString(Charsets.UTF_8))
        assertEquals(2, fixture.length())
        for (i in 0 until fixture.length()) {
            val row = fixture.getJSONObject(i)
            val text = row.getString("text")
            assertEquals("classify prompt for: $text", row.getString("classify"), Prompts.classify(text))
            assertEquals("extract prompt for: $text", row.getString("extract"), Prompts.extract(text))
        }
    }
}
